import type { Metadata } from "next";
import { absoluteUrl, siteConfig } from "./site";

/**
 * Default share image, generated by src/app/opengraph-image.tsx. Page-level
 * openGraph objects replace the root's file-based image, so it is set here.
 */
const DEFAULT_OG_IMAGE = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${siteConfig.name} – ${siteConfig.tagline}`,
};

type PageMetaInput = {
  /** Page-specific title. The root layout template appends " | Mark Imaging". */
  title: string;
  description: string;
  /** Path beginning with "/", used for the canonical URL and og:url. */
  path: string;
  /** Use the title exactly as given, without the brand suffix (home page). */
  absoluteTitle?: boolean;
  ogType?: "website" | "article";
  ogImage?: { url: string; alt: string; width?: number; height?: number };
  noIndex?: boolean;
  article?: { publishedTime: string; modifiedTime?: string; authors?: string[] };
};

/**
 * Builds complete, consistent metadata for a page: title, description,
 * canonical, Open Graph and X/Twitter. Every route must call this so no page
 * ships without a canonical or social tags.
 */
export function buildMetadata({
  title,
  description,
  path,
  absoluteTitle,
  ogType = "website",
  ogImage,
  noIndex,
  article,
}: PageMetaInput): Metadata {
  const url = absoluteUrl(path);
  const socialTitle = absoluteTitle ? title : `${title} | ${siteConfig.name}`;
  const image = ogImage ?? DEFAULT_OG_IMAGE;
  const images = [{ ...image, url: absoluteUrl(image.url) }];

  return {
    title: absoluteTitle ? { absolute: title } : title,
    description,
    alternates: { canonical: url },
    openGraph: {
      type: ogType,
      url,
      title: socialTitle,
      description,
      siteName: siteConfig.name,
      locale: siteConfig.locale,
      images,
      ...(article && ogType === "article" && {
        publishedTime: article.publishedTime,
        modifiedTime: article.modifiedTime,
        authors: article.authors,
      }),
    },
    twitter: {
      card: "summary_large_image",
      title: socialTitle,
      description,
      images: images.map((i) => i.url),
    },
    ...(noIndex && { robots: { index: false, follow: true } }),
  };
}
